def _parse_regex_csv(value: str) -> list[str]:
    """Split a comma-separated list of regex patterns, respecting regex syntax.

    Commas inside brackets ({...}), parentheses ((...)), and character classes ([...])
    are not treated as separators. Escape sequences are also handled.
    """
    result: list[str] = []
    current = ""

    # Track nesting levels
    paren_depth = 0  # (...)
    bracket_depth = 0  # {...}
    in_char_class = False  # [...]

    i = 0
    while i < len(value):
        char = value[i]

        # Handle escape sequences
        if char == "\\":
            # Append the backslash and the next character as-is
            current += char
            if i + 1 < len(value):
                i += 1
                current += value[i]
            i += 1
            continue

        # Handle character class (square brackets)
        if char == "[" and not in_char_class:
            in_char_class = True
            current += char
        elif char == "]" and in_char_class:
            in_char_class = False
            current += char
        # Only track other nesting when not in a character class
        elif not in_char_class:
            if char == "(":
                paren_depth += 1
                current += char
            elif char == ")":
                paren_depth = max(0, paren_depth - 1)
                current += char
            elif char == "{":
                bracket_depth += 1
                current += char
            elif char == "}":
                bracket_depth = max(0, bracket_depth - 1)
                current += char
            elif char == "," and paren_depth == 0 and bracket_depth == 0:
                # Found a separator comma
                result.append(current.strip())
                current = ""
            else:
                current += char
        else:
            current += char

        i += 1

    # Don't forget the last part
    if current.strip():
        result.append(current.strip())

    return result

def _regexp_csv_transfomer(value: str) -> Sequence[Pattern[str]]:
    """Transforms a comma separated list of regular expressions."""
    patterns: list[Pattern[str]] = []
    for pattern in _parse_regex_csv(value):
        patterns.append(_regex_transformer(pattern))
    return patterns


def _regexp_paths_csv_transfomer(value: str) -> Sequence[Pattern[str]]:
    """Transforms a comma separated list of regular expressions paths."""
    patterns: list[Pattern[str]] = []
    for pattern in _csv_transformer(value):
        patterns.append(
            re.compile(
                str(pathlib.PureWindowsPath(pattern)).replace("\\", "\\\\")
                + "|"
                + pathlib.PureWindowsPath(pattern).as_posix()
            )
        )
    return patterns

